portIds.add(report.id);reportStates.add(state);const v=w.versions.find(v=>v.id===report.versionId);if(!v)return fail();await decodeGeneratorReport(report,companyId,v)}}if(count>M76_DIESEL_MAX_VERSIONS)return fail();for(const s of r.sources){m71Keys(s,['binding','companyLabel','entityLabel','facilityLabel','sourceLabel','eligible','findings']);m71Keys(s.binding,['coverageVersionId','coverageVersionSha256','entityId','facilityId','sourceId','boundaryDecisionId']);if(typeof s.eligible!=='boolean'||!Array.isArray(s.findings)||!['companyLabel','entityLabel','facilityLabel','sourceLabel'].every(k=>typeof s[k as keyof typeof s]==='string')||!m71Uuid(s.binding.sourceId)||s.binding.coverageVersionId!==r.coverageHeadVersionId||!m71HashString(s.binding.coverageVersionSha256))return fail()}return r}catch{return fail()}}
async function request(actor:HostedWorkspaceActor,companyId:string,suffix:string,payload?:unknown){actor.signal?.throwIfAborted();if(!m71Uuid(companyId)||!actor.accessToken||/[\r\n]/.test(actor.accessToken))return fail();const response=await fetch(`/workspace-api/workspace/${companyId}/stationary-diesel${suffix}`,{method:payload===undefined?'GET':'POST',headers:{authorization:`Bearer ${actor.accessToken}`,...(payload===undefined?{}:{'content-type':'application/json'})},body:payload===undefined?undefined:JSON.stringify(payload),signal:actor.signal,cache:'no-store'});actor.signal?.throwIfAborted();if(response.status===401||response.status===403){actor.onUnauthorized?.();throw new Error('Your access changed. Sign in again to continue.')}if(!response.ok)throw new Error(response.status===409?'The source, boundary or review changed, or this statement is already assigned. Refresh and check the source before retrying.':response.status===422?'Check the source boundary, decimal quantity, statement, confirmation and required explanations. Nothing was saved.':'Stationary source data is unavailable. Retry the same action or refresh.');const text=await response.text();actor.signal?.throwIfAborted();if(new TextEncoder().encode(text).length>M76_DIESEL_MAX_RESPONSE_BYTES)return fail();return text}
export async function generatorRegisterRequest(a:HostedWorkspaceActor,c:string){return decodeGeneratorRegister(parseM71Json(await request(a,c,''),M76_DIESEL_MAX_RESPONSE_BYTES),c)}
export async function generatorSaveRequest(a:HostedWorkspaceActor,c:string,w:string|null,input:M76DieselSaveInput){if(w!==null&&!m71Uuid(w))return fail();return decodeGeneratorVersion(parseM71Json(await request(a,c,w?`/${w}/versions`:'',input),M76_DIESEL_MAX_RESPONSE_BYTES),c)}
export async function generatorReviewRequest(a:HostedWorkspaceActor,c:string,w:string,input:M76DieselReviewInput){if(!m71Uuid(w))return fail();return decodeGeneratorReview(parseM71Json(await request(a,c,`/${w}/reviews`,input),M76_DIESEL_MAX_RESPONSE_BYTES),c)}
export async function generatorReportRequest(a:HostedWorkspaceActor,c:string,w:string,input:M76DieselReportInput){if(!m71Uuid(w))return fail();const raw=parseM71Json(await request(a,c,`/${w}/reports`,input),M76_DIESEL_MAX_RESPONSE_BYTES);const version=await decodeGeneratorVersion(parseM71Json(await request(a,c,`/${w}/versions/${input.versionId}`),M76_DIESEL_MAX_RESPONSE_BYTES),c);return decodeGeneratorReport(raw,c,version)}
export async function generatorStatementDownload(a:HostedWorkspaceActor,c:string,w:string,v:M76DieselVersion){if(v.companyId!==c||v.worksheetId!==w||!v.statement||!m71Uuid(w))return fail();const text=await request(a,c,`/${w}/statements/${v.statement.id}/download`);if(text!==v.statement.text||await coverageSha256(text)!==v.statement.sha256)return fail();return text}
export async function generatorExportRequest(a:HostedWorkspaceActor,c:string,v:M76DieselVersion){if(v.companyId!==c||!m71Uuid(v.worksheetId)||!m71Uuid(v.id))return fail();const text=await request(a,c,`/${v.worksheetId}/versions/${v.id}/calculation-export`);await decodeGeneratorVersion(parseM71Json(text,M76_DIESEL_MAX_RESPONSE_BYTES),c);if(text!==m76DieselExport(v))return fail();return text}
export async function generatorReportDownload(a:HostedWorkspaceActor,c:string,w:string,r:M76DieselReport){if(r.companyId!==c||r.worksheetId!==w||!m71Uuid(w)||!m71Uuid(r.id))return fail();const version=await decodeGeneratorVersion(parseM71Json(await request(a,c,`/${w}/versions/${r.versionId}`),M76_DIESEL_MAX_RESPONSE_BYTES),c);await decodeGeneratorReport(r,c,version);const text=await request(a,c,`/${w}/reports/${r.id}/download`);if(text!==r.html||await coverageSha256(text)!==r.htmlSha256)return fail();return text}

