  const seed=await populateM76RecoveryFixture(op,name,55463),{companyId:company,users}=seed,owner=users.owner
  runtime=connect(name,'neuvetra_runtime');const ref=(await op.query<{project_ref:string}>('select project_ref from neuvetra.staging_target')).rows[0]!.project_ref,db=new (HostedWorkspaceDatabase as any)(runtime,ref) as HostedWorkspaceDatabase
  let roster=(await db.findStationaryEquipment(owner,company,authority))!,generator=(await db.findStationaryDiesel(owner,company,authority.diesel))!,head=generator.worksheets[0]!.versions.at(-1)!
  await decodeStationaryRegister(roster,company);await decodeGeneratorRegister(generator,company);expect(roster.reconciliation.status).toBe('reconciled_bounded_synthetic');events.push('Native positive fixture read by actual stationary and generator decoders')
  const historic=await db.findStationaryEquipmentReport(owner,company,roster.rosterId!,roster.reports.at(-1)!.id,authority),proof=await db.findStationaryEquipmentReportProof(owner,company,roster.rosterId!,roster.reports.at(-1)!.id,authority)
  const origin='http://127.0.0.1:37579',foreign=crypto.randomUUID();await op.query('insert into auth.users(id)values($1)',[foreign]);await provisionStagingRoster(op,{expectedProjectRef:ref,workspaceId:crypto.randomUUID(),ownerUserId:foreign,members:[]})
  const actors:any={owner,member:users.member,foreign},deps={database:db,origin,validateUser:async(token:string)=>actors[token]?{id:actors[token],email:null,phone:null,fullName:null}:null},routes={roster:createM76Routes({...deps,authorities:authority}),diesel:createM76DieselRoutes({...deps,authority:authority.diesel})}
  const http=(family:'roster'|'diesel',suffix='',token:string|null='owner',method='GET',body?:string,requestOrigin=origin)=>routes[family](new Request(`${origin}/workspace/${company}/${family==='roster'?'stationary-equipment':'stationary-diesel'}${suffix}`,{method,headers:{origin:requestOrigin,...token?{authorization:'Bearer '+token}:{}},...body===undefined?{}:{body}}))
  for(const family of ['roster','diesel']as const){expect((await http(family,'',null)).status).toBe(401);expect((await http(family,'','foreign')).status).toBe(404);expect((await http(family,'','owner','GET',undefined,'https://wrong.invalid')).status).toBe(403);expect((await http(family,'','member')).status).toBe(200);expect((await http(family,'','member','POST','{}')).status).toBe(403);expect((await http(family,'','owner','POST','{"x":1,"x":2}')).status).toBe(422)}
  await refuses(runtime.query('update neuvetra.stationary_diesel_versions set version_sha256=$1 where company_id=$2',['0'.repeat(64),company]));events.push('Both real routes enforce authentication, tenant, origin, member read-only and duplicate JSON; runtime DML denied')
  const report=generator.worksheets[0]!.reports.at(-1)!;await decodeGeneratorReport(report,company,head)
