  await Bun.write('evaluations/research-qa/m76-independent-native-ui-fixture.json',JSON.stringify({register:roster,generatorRegister:generator,owner,equipmentReviewer:users.equipmentReviewer,generatorReviewer:users.workpaperReviewer,report:historic,proof},null,2)+'\n')
  for(const f of oracle.numericFixtures.filter(f=>f.family==='stationary_diesel')){
   const input={...structuredClone(head.activity),quantityGallons:f.quantity,statement:{...head.activity.statement!,statedQuantityGallons:f.quantity},zeroReason:f.quantity==='0.000'?'Independent documented no fuel consumption, including tests.':null,expectedVersionId:head.id,expectedVersionSha256:head.versionSha256,correctionReason:'Independent source-cell arithmetic vector '+f.quantity,idempotencyKey:crypto.randomUUID()}
   const sql=(await op.query<{c:any}>('select neuvetra.m76_diesel_calculation($1::text::jsonb,$2) c',[JSON.stringify(input),'a'.repeat(64)])).rows[0]!.c;expect(components(sql)).toEqual(f.expected)
   head=await db.saveStationaryDiesel(owner,company,head.worksheetId,input,authority.diesel);expect(components(head.calculation)).toEqual(f.expected);const reread=(await http('diesel')).clone();expect(reread.status).toBe(200);await decodeGeneratorRegister(await reread.json(),company)
  }events.push('All nine independent generator vectors matched direct native SQL and persisted Python/server/HTTP/actual decoder: zero, minimum, irregular, maximum and both new half-even ties')
  roster=(await db.findStationaryEquipment(owner,company,authority))!;expect(roster.reconciliation.status).toBe('blocked');expect(roster.reconciliation.findings.some(f=>f.code==='dependency_stale')).toBe(true);expect(await db.findStationaryEquipmentReport(owner,company,roster.rosterId!,historic!.id,authority)).toEqual(historic);expect(await db.findStationaryEquipmentReportProof(owner,company,roster.rosterId!,historic!.id,authority)).toEqual(proof)
  const correction=()=>({...structuredClone(head.activity),expectedVersionId:head.id,expectedVersionSha256:head.versionSha256,correctionReason:'Independent evidence-only correction',idempotencyKey:crypto.randomUUID()})
