  const unreviewedReport=await db.createStationaryDieselReport(owner,company,head.worksheetId,{versionId:head.id,expectedVersionSha256:head.versionSha256,expectedDecisionId:null,expectedDecisionSha256:null,idempotencyKey:crypto.randomUUID()},authority.diesel)
  const review={versionId:head.id,expectedVersionSha256:head.versionSha256,decision:'accepted_bounded_internal' as const,note:'Independent supported native correction review.',acknowledgedLimitations:[...M76_DIESEL_LIMITATIONS],idempotencyKey:crypto.randomUUID()};await refuses(db.reviewStationaryDiesel(owner,company,head.worksheetId,review,authority.diesel));await db.reviewStationaryDiesel(users.workpaperReviewer,company,head.worksheetId,review,authority.diesel)
  generator=(await db.findStationaryDiesel(owner,company,authority.diesel))!;expect(generator.worksheets[0]!.reports.find(r=>r.id===unreviewedReport.id)).toEqual(unreviewedReport);await decodeGeneratorReport(unreviewedReport,company,generator.worksheets[0]!.versions.at(-1)!);events.push('No-op refused, statement-only and equipment label-only successors retained exact prior versions; null-review report stays exact after independent later review; self-review refused')
  const raceA=correction(),raceB=correction();raceA.statement!.description+=' Race A';raceB.statement!.description+=' Race B';const race=await Promise.allSettled([db.saveStationaryDiesel(owner,company,head.worksheetId,raceA,authority.diesel),db.saveStationaryDiesel(owner,company,head.worksheetId,raceB,authority.diesel)]);expect(race.filter(r=>r.status==='fulfilled').length).toBe(1);expect(race.filter(r=>r.status==='rejected').length).toBe(1);events.push('Concurrent corrections retain exactly one successor')
  await Bun.write('evaluations/research-qa/m76-independent-native-result.json',JSON.stringify({status:'passed',database:name,template:source,schema:receipts.at(-1),company,seed,events,limitations:['Synthetic isolated clone only; production author fixture used solely for setup. Native tests and assertions independently authored.','Cross-family evidence and coordinated stored-byte forgery run separately. No hosted or release acceptance.']},null,2)+'\n')
