export const M76_DIESEL_REPORT_TEMPLATE=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Synthetic stationary generator source report</title><style>body{font:16px/1.5 system-ui;max-width:950px;margin:2rem auto;padding:0 1rem;color:#172f2c;overflow-wrap:anywhere}th,td{padding:.45rem;text-align:left;border-bottom:1px solid #ccd8d0}table{width:100%;border-collapse:collapse}pre{white-space:pre-wrap;font:13px/1.5 monospace}@media print{body{font-size:11pt;margin:0;max-width:none}h2{break-after:avoid}}</style></head><body><h1>Stationary generator subtotal — synthetic internal draft</h1><p>Development candidate. Factors and method are not released. Scope 1 and corporate inventory incomplete. No filing determination or external assurance.</p><h2>Equipment, consumption and evidence</h2>{{facts}}<h2>Gas results</h2>{{results}}<h2>Open findings</h2>{{findings}}<p>Consumed U.S. gallons are converted to HHV MMBtu using the default 0.138 MMBtu/gallon estimate because supplier-specific HHV and carbon data are unavailable. Gas masses and exact total retain computational precision. Only the displayed source subtotal is rounded to four decimals with half-even rounding. Combustion only; upstream emissions and other source families are excluded. No aggregate emissions.</p><details><summary>Exact version and provenance</summary><pre>{{snapshot}}</pre></details></body></html>`
export const m76DieselReportSnapshot=(version:M76DieselVersion,review:M76DieselReview|null)=>({profile:'m76-generator-source-report-v1' as const,version:{...version,review:null},review})
const esc=(value:unknown)=>String(value??'Missing').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!))
export function m76DieselReportFacts(snapshot:ReturnType<typeof m76DieselReportSnapshot>):[string,unknown][]{const {version:v,review}=snapshot,a=v.activity,c=v.calculation,s=a.statement;return [['Company',v.coverageVersion.snapshot.companyLabel],['Entity',v.coverageVersion.snapshot.entities.find(x=>x.id===a.binding.entityId)?.legalName],['Facility',v.coverageVersion.snapshot.facilities.find(x=>x.id===a.binding.facilityId)?.name],['Source',v.coverageVersion.snapshot.sources.find(x=>x.id===a.binding.sourceId)?.name],['Equipment ID',a.equipment.assetId],['Identifier basis',a.equipment.identifierBasis],['Equipment type',a.equipment.equipmentType],['Engine type',a.equipment.engineType],['Installation',a.equipment.stationaryInstallation],['Control basis',a.equipment.controlBasis],['Control explanation',a.equipment.controlExplanation],['Fuel',a.equipment.fuel],['Fossil fraction',a.equipment.fossilFraction],['Fuel grade basis',a.equipment.fuelGradeBasis],['Period',a.period.start+' to '+a.period.endExclusive],['Entered consumed U.S. gallons',a.quantityGallons],['Stated consumed U.S. gallons',s?.statedQuantityGallons],['Activity status',v.activityStatus],['Manual confirmation',a.manualConfirmation],['Issuer',s?.issuer],['Reference',s?.reference],['Meter',s?.meterLabel],['Measurement basis',s?.measurementBasis],['Consumption boundary explanation',s?.consumptionBoundaryExplanation],['Default factor eligibility explanation',s?.defaultFactorEligibilityExplanation],['Supplier-specific HHV available',s?.supplierSpecificHhvAvailable],['Supplier-specific carbon available',s?.supplierSpecificCarbonAvailable],['Includes test and maintenance runs',s?.includesTesting],['Statement locator',v.statement?.locator],['Statement SHA-256',v.statement?.sha256],['Unresolved discrepancy explanation',a.discrepancyReason],['No-consumption explanation',a.zeroReason],['Derived HHV MMBtu',c?.derivedHhv.quantityMmbtu],['Exact source subtotal kg CO2e',c?.total.unrounded],['Displayed source subtotal kg CO2e',c?.total.display],['Method',c?.method.id],['Method version',c?.method.version],['Workbook SHA-256',c?.method.sourceSha256],['Factor locators',c?.method.factorCells.join(', ')],['GWP basis',c?.method.gwpAssessment],['Rights status',c?.method.rights],['Review as captured',review?.decision??'Unreviewed'],['Reviewer note',review?.note],['Correction reason',v.correctionReason]]}
export function m76DieselRenderReport(snapshot:ReturnType<typeof m76DieselReportSnapshot>):string{const v=snapshot.version,c=v.calculation,slots:Record<string,string>={facts:'<dl>'+m76DieselReportFacts(snapshot).map(([label,value])=>'<dt>'+label+'</dt><dd>'+esc(value)+'</dd>').join('')+'</dl>',results:c?'<table><thead><tr><th>Gas</th><th>Mass</th><th>kg CO2e</th></tr></thead><tbody>'+(['co2','ch4','n2o'] as const).map(key=>'<tr><th>'+key.toUpperCase()+'</th><td>'+esc(c.gasResults[key].mass)+' '+esc(c.gasResults[key].massUnit)+'</td><td>'+esc(c.gasResults[key].co2e)+'</td></tr>').join('')+'</tbody></table>':'<p>No emissions total was calculated. Required compatible activity or evidence is missing, unconfirmed or contradictory.</p>',findings:'<ul>'+v.findings.map(x=>'<li>'+esc(x.message)+'</li>').join('')+'</ul>',snapshot:esc(m76DieselCanonicalJson(snapshot))};return M76_DIESEL_REPORT_TEMPLATE.replace(/\{\{(facts|results|findings|snapshot)\}\}/g,(_,key:string)=>slots[key]!)}

