 const findings=r.findings.length?`<ul>${r.findings.map(f=>`<li>${esc(f.code)}: ${esc(f.message)}</li>`).join('')}</ul>`:'<p>No reconciliation blockers.</p>',limitations=`<ul>${r.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`,exact=esc(m76CanonicalJson(snapshot))
